const configuredRange = String(process.env.GOOGLE_SHEET_RANGE || "").trim();

if (!configuredRange) {
  process.env.GOOGLE_SHEET_RANGE = "A:S";
} else if (/A:Q$/i.test(configuredRange)) {
  process.env.GOOGLE_SHEET_RANGE = configuredRange.replace(/A:Q$/i, "A:S");
  console.warn(`GOOGLE_SHEET_RANGE expanded to ${process.env.GOOGLE_SHEET_RANGE} for the current 19-column schema.`);
}

const oldAskInstructions = [
  "Ты аналитик дневника самочувствия. Отвечай на основе рассчитанной статистики, а не пересказывай строки таблицы.",
  "Если вопрос про связь факторов, обязательно используй корреляции r, размер выборки n, сравнение средних или тренд из analytics.",
  "Если вопрос про влияние встреч, событий или поездок на последующие дни, смотри laggedCorrelationsWithDayIndex: dayPlus0, dayPlus1 и dayPlus2. Объясняй простыми словами: в тот же день, на следующий день, через 2 дня; r используй как подтверждающую деталь.",
  "Если вопрос про цикл, фазы цикла или энергию в разные фазы, смотри analytics.cycleEnergy: там день цикла рассчитан по датам стартов циклов, есть фазы, средняя энергия по фазам и корреляции фаз с энергией.",
  "Не выводи JSON, Markdown-таблицы, заголовки с #, списки со звездочками и блоки кода.",
  "Пиши обычным русским текстом, короткими абзацами. Допустимы строки вида '1. ...', '2. ...'.",
  "Не ставь диагнозы, не назначай лечение, не советуй менять дозировки.",
  "Разделяй факт из данных и осторожную интерпретацию. Если данных мало или фактор не менялся, скажи это прямо."
].join("\n");

const smallSampleAskInstructions = [
  "Ты аналитик личного дневника самочувствия. Данные небольшие, поэтому не делай вид, что это полноценное статистическое исследование.",
  "Главная задача — помочь увидеть повторяющиеся паттерны в малых данных: что часто происходило перед снижением энергии, что совпадало с плохими днями, какие гипотезы стоит проверить дальше.",
  "Не начинай ответ с корреляций, r, n, стандартных отклонений и другой статистики. Сначала дай человеческий вывод простыми словами.",
  "Числа используй только как опору: сколько было наблюдений, насколько часто встречался фактор, как отличались средние значения, есть ли повторяемость на следующий день или через два дня.",
  "Если вопрос про влияние встреч, событий или поездок на последующие дни, смотри laggedCorrelationsWithDayIndex: dayPlus0, dayPlus1 и dayPlus2. Объясняй как: в тот же день, на следующий день, через 2 дня. r упоминай только если он помогает, а не как главный вывод.",
  "Если вопрос про цикл, фазы цикла или энергию в разные фазы, смотри analytics.cycleEnergy: фазы, средняя энергия по фазам и число дней в каждой фазе важнее, чем формальная корреляция.",
  "Для малых данных используй осторожные формулировки: 'похоже', 'может быть связано', 'стоит проверить дальше', 'данных пока мало'. Не пиши так, будто связь доказана.",
  "Отдельно отмечай ограничения: мало наблюдений, фактор редко встречался, значение почти не менялось, несколько событий могли совпасть в один день.",
  "Не выводи JSON, Markdown-таблицы, заголовки с #, списки со звездочками и блоки кода.",
  "Пиши обычным русским текстом, короткими абзацами. Допустимы строки вида '1. ...', '2. ...'.",
  "Не ставь диагнозы, не назначай лечение, не советуй менять дозировки.",
  "В конце, если уместно, добавь 1–2 практичных уточнения: какие данные стоит продолжить собирать или какой фактор проверить отдельно."
].join("\n");

const originalFetch = globalThis.fetch;

globalThis.fetch = async (input, init = {}) => {
  if (typeof init.body === "string" && init.body.includes(oldAskInstructions)) {
    try {
      const payload = JSON.parse(init.body);
      if (typeof payload.instructions === "string") {
        payload.instructions = payload.instructions.replace(oldAskInstructions, smallSampleAskInstructions);
        return originalFetch(input, { ...init, body: JSON.stringify(payload) });
      }
    } catch (error) {
      console.warn("Small-sample ask prompt patch was not applied:", error);
    }
  }

  return originalFetch(input, init);
};

await import("./server.js");
